{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who the incoming caregiver is (e.g., spouse, adult child, paid helper) and whether their role or authority level affects what tasks they can take on.",
      "why_it_matters": "Different actors may require different levels of detail in the handover or have different permissions, which affects how the handover can be standardized or automated."
    },
    {
      "category": "input",
      "gap": "There is no description of what information is gathered or reviewed before the handover conversation begins (e.g., a task list, medication log, care notes from the day).",
      "why_it_matters": "Knowing the source data for the handover determines whether it can be pulled automatically from existing records or must be manually compiled."
    },
    {
      "category": "output",
      "gap": "It is unclear what form the handover information takes — whether it is verbal only, written on paper, entered into an app, or sent as a message.",
      "why_it_matters": "The output format determines whether the handover is capturable, auditable, and automatable, and whether there is a persistent record."
    },
    {
      "category": "manual_effort",
      "gap": "The specific tasks involved in 'getting things ready for the next day' are not described (e.g., preparing medications, laying out supplies, scheduling appointments).",
      "why_it_matters": "Without knowing which preparation tasks are performed, it is impossible to assess which steps are repetitive and suitable for automation or reminders."
    },
    {
      "category": "decision",
      "gap": "It is not clear how decisions are made about what 'still needs doing' — whether this is based on a checklist, memory, or review of completed tasks.",
      "why_it_matters": "If the decision relies on memory or informal judgment, there is a high risk of omissions; a structured decision rule would be needed for any automation."
    },
    {
      "category": "exception",
      "gap": "There is no information about what happens when the incoming caregiver is unavailable or arrives late, or when a critical task was not completed during the day.",
      "why_it_matters": "Exception handling determines whether the workflow needs escalation paths or fallback steps, which are essential for reliable automation design."
    },
    {
      "category": "frequency",
      "gap": "It is not stated how often this handover occurs (e.g., every evening, only on certain days) or whether the next-day preparation routine varies by day of the week.",
      "why_it_matters": "Frequency affects the priority of automation investment and whether scheduling logic needs to account for variable patterns."
    },
    {
      "category": "data_availability",
      "gap": "It is unknown whether a record of tasks completed during the day exists in any system or is tracked informally, making it unclear what data is available to support the handover.",
      "why_it_matters": "Automation of the handover summary depends on whether completed and pending task data can be retrieved programmatically."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "When you tell the incoming caregiver what still needs doing, is that information communicated verbally, written down, or recorded somewhere like an app or shared document?",
      "targets": ["output"]
    },
    {
      "id": "Q2",
      "question": "How do you determine which tasks still need to be done at handover time — do you work from a checklist, review a log of what was completed during the day, or rely on memory?",
      "targets": ["decision", "input"]
    },
    {
      "id": "Q3",
      "question": "Can you describe the specific steps involved in getting things ready for the next day — for example, does this include preparing medications, laying out equipment, or scheduling anything?",
      "targets": ["manual_effort"]
    },
    {
      "id": "Q4",
      "question": "Does this evening handover and preparation routine happen every day, or only on certain days, and does the content of the routine change depending on the day?",
      "targets": ["frequency"]
    },
    {
      "id": "Q5",
      "question": "What happens if the person taking over in the evening is unavailable or significantly delayed — is there a backup plan or does the current caregiver continue until they arrive?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "Is there any existing tool, app, or written record used during the day to track what care tasks have been completed, or is that tracking done entirely from memory?",
      "targets": ["data_availability"]
    }
  ]
}
